// --- decide(): pure decision logic (mirrored 1:1 by tests/decide.test.js) ---
// state.fired[key]    true = alerted, latched; false = armed; absent = never seen (cold start)
// state.safeRuns[key] consecutive scheduled runs on the safe side while latched
function decide(rules, px, state, fmt) {
  state.fired = state.fired || {};
  state.safeRuns = state.safeRuns || {};
  const out = [];
  for (const r of rules) {
    const p = px[r.sym];
    if (!Number.isFinite(p)) continue; // no price this run: change nothing
    const hit = r.op === '>' ? p > r.lvl : p < r.lvl;
    if (!(r.key in state.fired)) {
      // Cold-start seed (thanks u/vlotstroom): fresh import / duplicate starts with empty state.
      // Already past the level on the first look -> latch silently, no alert.
      state.fired[r.key] = hit;
      state.safeRuns[r.key] = 0;
      continue;
    }
    if (state.fired[r.key]) {
      // Two-run re-arm (thanks u/Fit-Corner2382): stay latched until 2 consecutive safe runs.
      if (hit) state.safeRuns[r.key] = 0;
      else {
        const n = (state.safeRuns[r.key] || 0) + 1;
        if (n >= 2) { state.fired[r.key] = false; state.safeRuns[r.key] = 0; }
        else state.safeRuns[r.key] = n;
      }
      continue;
    }
    // armed
    if (hit) {
      // NOT written here: Notify applies fired + streak together only after a successful send.
      out.push({ json: { text: `🎯 <b>${r.sym}</b> ${r.op === '>' ? 'above' : 'below'} ${fmt(r.lvl, 8)} — now ${fmt(p, 8)}`,
        commit: [{ path: ['fired', r.key], value: true }, { path: ['safeRuns', r.key], value: 0 }] } });
    } else state.safeRuns[r.key] = 0;
  }
  return out;
}
// --- end decide() ---
const cfg = $('Config').first().json;
const http = (url, opts = {}) => this.helpers.httpRequest({ url, json: true, timeout: 20000, ...opts });
const state = $getWorkflowStaticData('global'); // persists between *active* (scheduled) runs
const fmt = (n, d = 2) => Number(n).toLocaleString('en-US', { maximumFractionDigits: d });

const rules = String(cfg.levels).split(',').map(s => s.trim()).filter(Boolean).map(s => {
  const m = s.match(/^([A-Z0-9]+)\s*([<>])\s*([\d.]+)$/i);
  if (!m) throw new Error(`Bad level "${s}". Use e.g. BTCUSDT>100000`);
  return { key: s, sym: m[1].toUpperCase(), op: m[2], lvl: Number(m[3]) };
});
const syms = [...new Set(rules.map(r => r.sym))];
const prices = await http(`https://data-api.binance.vision/api/v3/ticker/price?symbols=${encodeURIComponent(JSON.stringify(syms))}`);
const px = Object.fromEntries(prices.map(p => [p.symbol, Number(p.price)]));
const out = decide(rules, px, state, fmt);
return out.length ? out : [{ json: { info: 'No level crossed', prices: px } }];

// Sends every incoming item's `text` to Telegram and/or Discord.
// Leave tokens empty to run in dry-run mode (messages are returned, not sent).
// Reliability: the Check node never marks an alert as "done" itself. It attaches a
// `commit` list of state updates to each alert; they are applied here ONLY after the
// message was delivered. A failed send is reported and retried on the next run.
const cfg = $('Config').first().json;
const state = $getWorkflowStaticData('global');
const apply = (ops = []) => {
  for (const { path, value, op } of ops) {
    let o = state;
    for (const k of path.slice(0, -1)) o = o[k] = o[k] || {};
    const last = path[path.length - 1];
    if (op === 'push') (o[last] = o[last] || []).push(value); else o[last] = value;
  }
};
const out = [];
let failed = 0;
const deferred = [];
for (const item of $input.all()) {
  const { text, commit, commitIfAllSent } = item.json;
  if (commitIfAllSent) deferred.push(commitIfAllSent);
  if (!text) { apply(commit); continue; }
  const sent = [];
  try {
    if (cfg.telegramBotToken && cfg.telegramChatId) {
      const base = cfg.telegramApiBase || 'https://api.telegram.org';
      const r = await this.helpers.httpRequest({
        method: 'POST', url: `${base}/bot${cfg.telegramBotToken}/sendMessage`, json: true,
        body: { chat_id: cfg.telegramChatId, text, parse_mode: 'HTML', disable_web_page_preview: true },
      });
      if (r && r.ok === false) throw new Error(`Telegram: ${r.description || 'not ok'}`);
      sent.push('telegram');
    }
    if (cfg.discordWebhookUrl) {
      await this.helpers.httpRequest({
        method: 'POST', url: cfg.discordWebhookUrl, json: true,
        body: { content: text.replace(/<\/?b>/g, '**').replace(/<[^>]+>/g, '') },
      });
      sent.push('discord');
    }
  } catch (e) {
    failed++;
    out.push({ json: { text, sent, error: String(e.message || e), willRetry: true } });
    continue;
  }
  apply(commit); // delivered (or dry-run): now it is safe to remember it
  out.push({ json: { text, sent, dryRun: sent.length === 0 } });
}
if (!failed) deferred.forEach(apply);
return out;
